audits = (
    pd.concat([Table_0.assign(Year=2023), Table_1.assign(Year=2024)], ignore_index=True)
      .drop_duplicates(subset=['PCP','PRO','RSL','CLS','RCP','GHE','Activity','PSL','MSM','MIN'])
)

pcp_pct = (
    audits.groupby('Activity')
          .apply(lambda df: pd.Series({
              'Total': df['TradingName'].nunique(),
              'PCP_Yes': df.loc[df['PCP'] == 'Yes', 'TradingName'].nunique()
          }))
          .reset_index()
)
pcp_pct['PCP_Percent'] = (pcp_pct['PCP_Yes'] / pcp_pct['Total'] * 100).round(2)

combined = pd.concat([Table_0, Table_1], ignore_index=True)
grade_stats = (
    combined
    .groupby('Grade', as_index=False)
    .agg({
        'Number of Posts in FTE': 'sum',
        'Payscale Minimum (£)': 'mean',
        'Payscale Maximum (£)': 'mean'
    })
    .rename(columns={
        'Number of Posts in FTE': 'Total Posts (FTE)',
        'Payscale Minimum (£)': 'Avg Payscale Min (£)',
        'Payscale Maximum (£)': 'Avg Payscale Max (£)'
    })
)
